{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C14", "C15", "C03", "C04", "C11", "C17", "C66", "C56", "C65"],
  "contradictory_card_ids": ["C29", "C42"],
  "prediction_basis_card_ids": ["C14", "C15", "C03", "C04", "C11", "C17", "C66", "C56", "C65"],
  "claims": [
    {
      "claim": "The query is a saligenin beta2-agonist with a long lipophilic dichlorobenzyl-ethoxy side chain; the closest L4 analog is salmeterol, whose aqueous solubility at pH 6.5 was 122 µg/mL, while salbutamol and formoterol were >72 and >103 µg/mL. These solubility values are measurable but do not by themselves establish F >= 20%.",
      "card_ids": ["C97", "C141", "C129"]
    },
    {
      "claim": "Salbutamol absolute oral bioavailability in fasting subjects was 7.2% and 11.4%, both below the 20% threshold.",
      "card_ids": ["C14", "C15"]
    },
    {
      "claim": "Bambuterol human oral bioavailability is about 10% of the administered dose, below the 20% threshold; dog and rat values are species-specific and do not override the human outcome.",
      "card_ids": ["C03", "C04", "C11", "C21", "C31"]
    },
    {
      "claim": "Epanolol, a related aryloxypropanolamine beta-blocker, had absolute oral bioavailability of 5.85 ± 2.55% with food, below the 20% threshold.",
      "card_ids": ["C17"]
    },
    {
      "claim": "Batefenterol oral parent exposure was negligible: all parent concentrations were non-quantifiable after a 200 µg oral dose, with pooled parent AUC0-t of 0.614 h·pgEq/mL, supporting low oral bioavailability for a related lipophilic beta2 agonist.",
      "card_ids": ["C66", "C56", "C65"]
    },
    {
      "claim": "Phenylephrine L2 absolute estimates around 37.5–38% are above the threshold but are less transferable because phenylephrine lacks the saligenin head group and undergoes extensive presystemic metabolism; L1 reports poor oral bioavailability.",
      "card_ids": ["C10", "C29", "C38", "C42"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C97", "C141", "C129"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule.",
    "No matched oral-versus-IV exposure or IV reference for the query.",
    "No query-specific solubility, permeability, or intestinal absorption measurement; L4 closest is salmeterol solubility (C97), and Caco-2 records are for propranolol.",
    "Transfer from salbutamol, bambuterol, epanolol, and batefenterol is structural/pharmacological, not exact.",
    "Phenylephrine L2 absolute values around 38% conflict with its qualitative L1 poor outcome and are less transferable.",
    "No formulation-specific oral pharmacokinetic data for the query."
  ],
  "decision_summary": "L4 adds only solubility data for structurally related beta2 agonists (salmeterol, salbutamol, formoterol) and no query-specific permeability or absorption measurement; these records do not overturn the prior low prediction based on direct human oral bioavailability values below 20% for salbutamol, bambuterol, and epanolol, and negligible oral parent exposure for batefenterol. Prediction remains low with moderate confidence."
}

